/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_registrar_saldo_cliente` AFTER UPDATE ON `cuenta_bancaria` FOR EACH ROW BEGIN
