/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cancelar_compra`(IN p_idCompra INT, IN p_idCliente INT)
BEGIN
    DECLARE v_cliente INT;
    DECLARE v_boleto INT;
    DECLARE v_cuentaCliente INT;
    DECLARE v_cuentaPromotora INT;
    DECLARE v_precio DECIMAL(10,2);
    DECLARE v_hora DATETIME;
    DECLARE v_estatus VARCHAR(15);
    DECLARE v_saldoCliente DECIMAL(12,2);
    DECLARE v_saldoPromotora DECIMAL(12,2);
    DECLARE v_lock INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        IF v_lock = 1 THEN DO RELEASE_LOCK('tuticket_operaciones'); END IF;
        RESIGNAL;
    END;
    SELECT GET_LOCK('tuticket_operaciones', 10) INTO v_lock;
    IF v_lock IS NULL OR v_lock <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El sistema estÃ¡ ocupado. Intenta nuevamente.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM compra WHERE idCompra = p_idCompra) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La compra no existe.';
    END IF;
    SELECT c.idCliente, c.idBoleto, c.idCuenta_Bancaria, e.idCuenta_Bancaria,
           c.precioFinal, c.horaCompra, c.estatus
    INTO v_cliente, v_boleto, v_cuentaCliente, v_cuentaPromotora, v_precio, v_hora, v_estatus
    FROM compra c JOIN boleto b ON c.idBoleto=b.idBoleto
    JOIN evento e ON b.idEvento=e.idEvento WHERE c.idCompra=p_idCompra;
    IF v_cliente <> p_idCliente THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La compra no pertenece al cliente.';
    END IF;
    IF v_estatus <> 'comprado' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Solo se puede cancelar una compra activa.';
    END IF;
    IF NOW() > DATE_ADD(v_hora, INTERVAL 24 HOUR) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya transcurrieron las 24 horas para cancelar.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM cuenta_cliente WHERE idCuenta_Bancaria=v_cuentaCliente AND idCliente=p_idCliente) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cuenta de pago no pertenece al cliente.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM boleto WHERE idBoleto=v_boleto AND estatus='vendido') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El boleto no estÃ¡ vendido.';
    END IF;
    SELECT saldo INTO v_saldoCliente FROM cuenta_bancaria WHERE idCuenta_Bancaria=v_cuentaCliente;
    SELECT saldo INTO v_saldoPromotora FROM cuenta_bancaria WHERE idCuenta_Bancaria=v_cuentaPromotora;
    IF v_saldoPromotora < v_precio OR v_saldoCliente + v_precio > 9999999999.99 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Los saldos no permiten realizar el reembolso.';
    END IF;
    -- Todas las precondiciones se revisan antes del primer cambio.
    UPDATE cuenta_bancaria SET saldo=saldo-v_precio WHERE idCuenta_Bancaria=v_cuentaPromotora;
    UPDATE cuenta_bancaria SET saldo=saldo+v_precio WHERE idCuenta_Bancaria=v_cuentaCliente;
    UPDATE compra SET estatus='cancelado',horaCancelacion=NOW() WHERE idCompra=p_idCompra;
    UPDATE boleto SET estatus='disponible' WHERE idBoleto=v_boleto;
    DO RELEASE_LOCK('tuticket_operaciones');
END ;;
DELIMITER ;
